INSERT INTO public.posts (id, author_id, title, content, tags, likes_count, comments_count, views_count, created_at, updated_at) VALUES (2, 9, '政企数字化转型中的大模型合规边界探讨', '在一次国家政务项目中，我们遭遇了模型输出合规性的严峻挑战。整理了几条实战经验，关于敏感词过滤、数据脱敏流程以及审计日志的最佳实践…', '{#合规,#政企数字化,#大模型}', 620, 31, 1800, '2026-03-25 06:27:33.231871', '2026-03-25 06:27:33.231871');
INSERT INTO public.posts (id, author_id, title, content, tags, likes_count, comments_count, views_count, created_at, updated_at) VALUES (3, 9, '新手OPC如何快速获得第一单？我的三个月复盘', '三个月前我刚注册接单吧，什么都不会。现在已经完成了4单，累计结算2.8万。分享一下我踩过的坑和经验总结…', '{#新手攻略,#接单经验,#成长}', 891, 67, 3200, '2026-03-25 06:27:33.235188', '2026-03-25 06:27:33.235188');
INSERT INTO public.posts (id, author_id, title, content, tags, likes_count, comments_count, views_count, created_at, updated_at) VALUES (1, 9, '关于 #VibeCoding 在工业级项目中的实际落地探讨', '最近在处理一个复杂的LLM集成项目，我们尝试引入了VibeCoding的概念。不仅提高了Prompt的容错率，还显著降低了上下文窗口的损耗。这里分享一些心得…', '{#VibeCoding,#AIPrompting,#TechTalk}', 1240, 86, 4500, '2026-03-25 06:27:33.228009', '2026-03-25 06:27:33.228009');


